    "question_ms": "Semasa Ujian Amali JPJ Bahagian II (Litar) dan Bahagian III (Jalan Raya), mengapakah pemarkahan calon dibahagikan kepada 'Kesalahan Biasa' (Markah Tolakan) dan 'Kesalahan Mandatori'?",
