    "order_index": 44,
    "question_en": "During the JPJ Part II (Circuit) and Part III (Road) practical driving test, why are candidates Evaluated using two grading sections: 'Kesalahan Biasa' (Demerit Marks) and 'Kesalahan Mandatori' (Mandatory Errors)?",
    "question_ms": "Semasa Ujian Amali JPJ Bahagian II (Litar) dan Bahagian III (Jalan Raya), mengapakah pemarkahan calon dibahagikan kepada 'Kesalahan Biasa' (Markah Tolakan) dan 'Kesalahan Mandatori'?",
    "options_en": [
      "Mandatory errors give bonus marks to the candidate",
      "A candidate fails immediately if they commit even ONE Mandatory Error (Kesalahan Mandatori, such as rolling back on the hill, hitting a kerb/pole, not wearing a seatbelt, or failing to stop at a stop line), OR if their minor error deductions drop their total score below the minimum passing mark (80%)",
      "Candidates are allowed up to 5 Mandatory Errors before failing",
      "Only the circuit test is graded and the road test is ungraded in accordance with manufacturer vehicle service specifications to minimise mechanical fatigue and avoid unexpected part failure while maintaining a firm two-handed grip on the steering wheel to prevent hazardous brake overheating and loss of stopping force"
    ],
    "options_ms": [
      "Kesalahan Mandatori memberikan markah bonus kepada calon",
      "Calon akan dikira GAGAL serta-merta sekiranya melakukan walau SATU Kesalahan Mandatori (seperti menggelongsor di bukit, melanggar tiang/bebendul, tidak memakai tali pinggang keledar, atau gagal berhenti di garisan berhenti), ATAU jika markah keseluruhan jatuh di bawah markah lulus minimum",
      "Calon dibenarkan melakukan sehingga 5 Kesalahan Mandatori sebelum gagal",
      "Hanya ujian litar diambil kira manakala ujian jalan raya tiada markah mengikut piawaian spesifikasi penyelenggaraan pengeluar kenderaan untuk mengurangkan kehausan mekanikal dan mengelakkan kerosakan komponen sambil memegang stereng dengan kemas menggunakan kedua-dua belah tangan bagi mengelakkan kepanasan melampau brek dan kehilangan daya cengkaman"
    ],
    "correct_index": 1,
    "explanation_en": "Avoiding every Mandatory Error (Kesalahan Mandatori) is critical to passing both Bahagian II (Circuit) and Bahagian III (Road).",
